const responseBody = pm.response.text();

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response body is not empty", function () {
    pm.expect(responseBody).to.not.be.empty;
});

pm.test("Response contains SOAP Envelope", function () {
    pm.expect(responseBody).to.include("soap:Envelope");
});

pm.test("Response contains SOAP Body", function () {
    pm.expect(responseBody).to.include("soap:Body");
});

pm.test("Response contains ISBN13 response", function () {
    pm.expect(responseBody).to.include("IsValidISBN13Response");
});

pm.test("Response contains ISBN13 result", function () {
    pm.expect(responseBody).to.include("IsValidISBN13Result");
});

pm.test("ISBN13 result is true", function () {
    pm.expect(responseBody).to.include(
        "<m:IsValidISBN13Result>true</m:IsValidISBN13Result>"
    );
});

pm.test("Response contains ISBN namespace", function () {
    pm.expect(responseBody).to.include(
        "http://webservices.daehosting.com/ISBN"
    );
});

pm.test("Response has Content-Type header", function () {
    pm.expect(
        pm.response.headers.has("Content-Type")
    ).to.eql(true);
});

pm.test("Response Content-Type contains XML", function () {
    pm.expect(
        pm.response.headers.get("Content-Type").toLowerCase()
    ).to.include("xml");
});

